        {
            entity.HasMany(e => e.PriceCategories)
                .WithOne()
                .HasForeignKey(pc => pc.EventId)
                .OnDelete(DeleteBehavior.Restrict);

            entity.HasMany(e => e.BookingPositions)
                .WithOne()
                .HasForeignKey(bp => bp.EventId)
                .OnDelete(DeleteBehavior.Restrict);
        });

