        {
            entity.Property(pc => pc.Preis).HasPrecision(10, 2);
        });

        modelBuilder.Entity<Booking>(entity =>
        {
            entity.Property(b => b.Reference)
                .HasMaxLength(8)
                .IsRequired()
                .UseCollation("SQL_Latin1_General_CP1_CI_AS");
